# In Standard Python 3.13: Spawning 4 threads runs on 1 CPU core at 100% load
# Total execution time equals sequential run time (~4.0s).
import threading, time

def heavy_work():
  sum(i * i for i in range(15_000_000))

start = time.perf_counter()
threads = [threading.Thread(target=heavy_work) for _ in range(4)]
for t in threads: t.start()
for t in threads: t.join()
print(f'Standard Python Time: {time.perf_counter() - start:.2f}s')
